<?php
declare(strict_types=1);
namespace App\Models;
use App\Models\Concerns\HasPublicId;
use App\Services\BranchContext;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\SoftDeletes;
class Book extends Model { use HasPublicId,SoftDeletes; protected $fillable=['sku','isbn','barcode','title','subtitle','author','publisher','edition','subject','language','category','media_format','default_audience','purchase_price','selling_price','tax_rate','minimum_stock','reserved_quantity','shelf_location','cover_path','is_active','notes']; protected $appends=['available_quantity']; protected function casts():array{return ['purchase_price'=>'decimal:2','selling_price'=>'decimal:2','tax_rate'=>'decimal:2','is_active'=>'boolean'];} public function scopeActive($query){return $query->where('is_active',true);} public function scopeWithBranchStock($query,?int $branchId=null){$branchId ??= app(BranchContext::class)->id();return $query->with(['branchStocks'=>fn($stocks)=>$stocks->where('branch_id',$branchId)])->withSum(['custodyStocks as branch_held_quantity'=>fn($stocks)=>$stocks->where('branch_id',$branchId)],'quantity_on_hand');} public function getAvailableQuantityAttribute():int{$stock=$this->branchStock();$quantity=$stock?(int)$stock->quantity_on_hand:(int)$this->stock_on_hand;$reserved=$stock?(int)$stock->reserved_quantity:(int)$this->reserved_quantity;return $quantity-$reserved-(int)($this->attributes['branch_held_quantity']??0);} public function getBranchQuantityAttribute():int{$stock=$this->branchStock();return $stock?(int)$stock->quantity_on_hand:(int)$this->stock_on_hand;} public function movements(){return $this->hasMany(StockMovement::class);} public function branchStocks(){return $this->hasMany(BranchBookStock::class);} public function custodyStocks(){return $this->hasMany(UserBookStock::class);} public function gradeUsages(){return $this->hasMany(BookGradeUsage::class);} private function branchStock():?BranchBookStock{if($this->relationLoaded('branchStocks'))return $this->branchStocks->first();if(!$this->exists)return null;return $this->branchStocks()->where('branch_id',app(BranchContext::class)->id())->first();} }
